local _, WFJ = ...
WFJ.Data.add("book", {
  ["bea759b528ce280a"] = { "La nuova ⟦Horde=Orda⟧, guidata da capi veterani come Grom Hellscream e Kilrogg Deadeye (del clan Bleeding Hollow), colse di sorpresa le forze di difesa dell'⟦Alliance=Alleanza⟧ e mise a ferro e fuoco le campagne. Sotto il comando chirurgico di Ner'zhul, gli orchi raccolsero in fretta i manufatti che servivano loro e fuggirono al sicuro su Draenor.", "." },
  ["beae61b19caf8258"] = { "Mastro Longbeard,\n\nCome sai, noi Stormpike abbiamo occhio per l'eccellenza, e la qualità dei tuoi scudi non è certo un mistero per noi.\n\nPerciò desidero commissionarti uno di questi scudi. Ho incluso le specifiche nella pagina seguente:", "." },
  ["beaf601af7050c8c"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">\nCapitolo 3: IL PILASTRO OCCIDENTALE\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_west\" align=\"left\"/>\n<P align=\"right\">Il pilastro<BR/>\noccidentale<BR/>\naccetta cristalli<BR/>\nrossi, verdi<BR/>\ne blu.</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">Il pilastro si concentra sull'energia che si può creare usando i cristalli rossi come fonte principale di potere.</P>\n</BODY>\n</HTML>", "." },
  ["becd1a1293db5a14"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">\nCombinazioni dei cristalli occidentali\n</H1>\n<BR/>\n<P align=\"left\">Ci sono due effetti possibili: uno che aumenta la tua protezione dai danni e uno che indebolisce le difese di un nemico.</P>\n<BR/>\n<P align=\"left\">DIFESA DEL CRISTALLO: richiede cristalli rossi e verdi.<BR/>Ti fornisce un aumento dell'Armatura.</P>\n<BR/>\n<P align=\"left\">RESA DEL CRISTALLO: richiede cristalli blu e rossi.<BR/>Può ridurre l'Armatura di un bersaglio specifico.\n</P>\n</BODY>\n</HTML>", "." },
  ["bef020a7ec6b661f"] = { "Il compito di vigilare su ⟦Ashenvale=Valtetra⟧ teneva occupata Tyrande, ma senza Malfurion al suo fianco conosceva ben poca gioia. Mentre i lunghi secoli passavano e i druidi dormivano, crebbe in lei il timore di una seconda invasione demoniaca. Non riusciva a scrollarsi di dosso la sensazione inquietante che la Legione Infuocata fosse ancora là fuori, oltre la Grande Oscurità del cielo, a tramare la sua vendetta contro gli elfi della notte e il mondo di Azeroth.", "." },
})
